-- More job boards. Ocelot reads ten more kinds of board (Workday, BambooHR, Breezy, Rippling, Pinpoint, Teamtailor,
-- Personio, Jobvite, JazzHR, iCIMS; src/lib/ats/readers.ts). The look-for list gains every board of these kinds
-- found in three months of the public web crawl (Common Crawl, CC-MAIN-2026-34, -39 and -43, read October 2026).
-- Crawl boards are checked once a month; a board with jobs that pass Ocelot's filters is added like any other.

alter table public.job_sources drop constraint job_sources_provider_check;
alter table public.job_sources add constraint job_sources_provider_check check (provider in ('greenhouse', 'lever', 'ashby', 'smartrecruiters', 'recruitee', 'workable', 'workday', 'bamboohr', 'breezy', 'rippling', 'pinpoint', 'teamtailor', 'personio', 'jobvite', 'jazzhr', 'icims'));
alter table public.board_candidates drop constraint board_candidates_provider_check;
alter table public.board_candidates add constraint board_candidates_provider_check check (provider in ('greenhouse', 'lever', 'ashby', 'smartrecruiters', 'recruitee', 'workable', 'workday', 'bamboohr', 'breezy', 'rippling', 'pinpoint', 'teamtailor', 'personio', 'jobvite', 'jazzhr', 'icims'));
alter table public.board_candidates add column found_by text not null default 'list' check (found_by in ('list', 'crawl'));

-- Names to check now: never checked first (names from the list, then known boards, then crawl boards), then a week
-- after the last check for names on the list and a month after for crawl boards.
create or replace function public.due_candidates(p_limit int default 40, p_now timestamptz default now())
returns setof public.board_candidates
language sql stable security definer set search_path = public as $$
  select * from board_candidates
  where not skip and source_id is null
    and (checked_at is null or checked_at < p_now - case when found_by = 'crawl' then interval '30 days' else interval '7 days' end)
  order by checked_at nulls first, found_by = 'crawl', (provider is null), slug
  limit p_limit
$$;
revoke execute on function public.due_candidates(int, timestamptz) from public, anon, authenticated;

on conflict (slug) do nothing;
-- A crawl board that's already a source, or already on the list under another name, isn't checked twice.
update public.board_candidates c set source_id = s.id from public.job_sources s
where c.found_by = 'crawl' and c.provider = s.provider and lower(c.board) = lower(s.board);
delete from public.board_candidates c using public.board_candidates l
where c.found_by = 'crawl' and l.found_by = 'list' and l.provider = c.provider and lower(l.board) = lower(c.board);

-- Boards found in the crawl sync once a day; boards on the list or added by Ocelot, every 6 hours.
alter table public.job_sources add column sync_hours int not null default 6 check (sync_hours between 1 and 168);
create or replace function public.due_sources(p_limit int default 10, p_now timestamptz default now())
returns setof public.job_sources
language sql stable security definer set search_path = public as $$
  select * from job_sources
  where active and (last_synced_at is null or last_synced_at < p_now - make_interval(hours => sync_hours))
  order by last_synced_at nulls first
  limit p_limit
$$;
revoke execute on function public.due_sources(int, timestamptz) from public, anon, authenticated;

-- Discovery stops adding boards once this many imported jobs are live, so the database stays inside its plan.
alter table public.app_settings add column max_imported_jobs int not null default 15000 check (max_imported_jobs >= 0);
